// exposed remote module: micro-frontend UI (kept lean; bundled into
// remoteEntry.js by the federation builder)
export function registerRemote(host) {
  const node = document.createElement('div');
  node.dataset.remote = 'remote-app';
  node.textContent = 'remote-app registered';
  const body = host && host.documentElement ? host.body : document.body;
  body.appendChild(node);
}

export function remoteInfo() {
  return 'remote-app v1';
}